// 데이터 API는 title, requester, category, priority만 저장한다. 담당과 요약을 잃지 않도록 title에 담는다.
const title = ('[' + category + ' · 담당 ' + assignee + '] ' + summary.text).replace(/\s+/g, ' ').slice(0, 500);
return [{ json: {
  invalid: false,
  request_id: b.request_id, user: b.user, title, summary: summary.text, category, priority, assignee,
  alert: alert.value, masked: summary.masked + alert.masked,
  // 본체가 넘기는 deadline_ms는 남은 시간(ms, 최소 500)이다. 받은 시각부터 세어 절대 시각으로 바꾼다 (최대 10초).
