} }];

function readHttp(j) {
  if (j && typeof j.statusCode === "number") {
    const body = j.body && typeof j.body === "object" ? j.body : {};
    return { ok: j.statusCode >= 200 && j.statusCode < 300 && !body.error, status: j.statusCode, body, errorCode: "" };
  }
  const text = j && j.error ? (typeof j.error === "string" ? j.error : JSON.stringify(j.error)) : "no_response";
  return { ok: false, status: null, body: {}, errorCode: text.slice(0, 300) };
}// ↓ lib/common.js 원문 복사
function shouldRetry(status, errorCode) {
  if (status === 429) return true;
  if (typeof status === 'number' && status >= 500) return true;
  if (!status && /TIMEDOUT|ABORTED|ECONNRESET|timeout/i.test(String(errorCode || ''))) return true;
  return false;
}
function backoffMs(attempt, retryAfterSeconds, capMs) {
  const cap = capMs || 3000;
  if (retryAfterSeconds && Number(retryAfterSeconds) > 0) return Math.min(Number(retryAfterSeconds) * 1000, cap);
  return Math.min(500 * Math.pow(2, Math.max(0, attempt - 1)), cap);
}
