return [{ json: { ...st, outcome: 'fail', reason } }];

const j = $json;
await new Promise(resolve => setTimeout(resolve, j.wait_ms));
const { outcome, wait_ms, ...state } = j;
return [{ json: { ...state, try_no: j.try_no + 1 } }];

